-- Vyapar parity Phase 3 (purchase side). Generated by drizzle-kit, then the RLS block below appended by hand.
-- Additive: every new column is nullable or has a default, and existing rows read as before (a purchase is a 'bill',
-- every line 'eligible', every expense an 'expense' with ITC on and paid in full). Two constraints change shape:
-- payment_allocations.invoice_id may now be null when the allocation is to a purchase bill (a check keeps exactly one
-- target), and expense category names are unique per kind, so an income and an expense category may share a name.
CREATE TABLE "expense_items" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"org_id" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"deleted_at" timestamp with time zone,
	"name" text NOT NULL,
	"sac" text DEFAULT '' NOT NULL,
	"default_rate" numeric(14, 2) DEFAULT 0 NOT NULL,
	"gst_rate" numeric(14, 2) DEFAULT 0 NOT NULL,
	"default_category_id" uuid,
	CONSTRAINT "expense_items_org_id_id" UNIQUE("org_id","id")
);
--> statement-breakpoint
CREATE TABLE "purchase_order_lines" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"org_id" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"deleted_at" timestamp with time zone,
	"order_id" uuid NOT NULL,
	"item_id" uuid,
	"name" text NOT NULL,
	"hsn" text DEFAULT '' NOT NULL,
	"quantity" numeric(14, 3) DEFAULT 1 NOT NULL,
	"rate" numeric(14, 2) DEFAULT 0 NOT NULL,
	"tax_percent" numeric(14, 2) DEFAULT 0 NOT NULL,
	"cess_percent" numeric(14, 2) DEFAULT 0 NOT NULL,
	"received_qty" numeric(14, 3) DEFAULT 0 NOT NULL
);
--> statement-breakpoint
CREATE TABLE "purchase_orders" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"org_id" uuid NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"deleted_at" timestamp with time zone,
	"business_id" uuid NOT NULL,
	"number" text NOT NULL,
	"supplier_id" uuid,
	"supplier_name" text DEFAULT '' NOT NULL,
	"supplier_gstin" text DEFAULT '' NOT NULL,
	"order_date" date NOT NULL,
	"expected_date" date,
	"interstate" boolean DEFAULT false NOT NULL,
	"status" text DEFAULT 'open' NOT NULL,
	"taxable_amount" numeric(14, 2) DEFAULT 0 NOT NULL,
	"total" numeric(14, 2) DEFAULT 0 NOT NULL,
	"data" jsonb DEFAULT '{}'::jsonb NOT NULL,
	CONSTRAINT "purchase_orders_org_id_id" UNIQUE("org_id","id")
);
